/* 02 이상한 칸 찾기: 배포본 8줄 × 8열 (탭 문자는 ⇥로 표시) */
(function(){
  const COLS=[0,1,5,10,11,17,22,23];
  const ROWS=[
    ['User 1',['0','0','2.92','1.7','1.69','0','0','0']],
    ['User 812',['2.29','2.27','1.56','1.44','1.27','5','2.36','5']],
    ['User 1347',['1.06','1.1','5','5','1.74','0','1.03','1.04']],
    ['User 1348',['1.06','1.1','5','5','1.74','0','.26⇥','']],
    ['User 1349',['1.06','1.1','5','5','1.74','0','1.03','1.04']],
    ['User 2713',['1.71','1.68','1.15','2⇥2.','','1.04','5','2.57']],
    ['User 2714',['1.71','1.7','1.51','0.82','0.83','5','2.58','2.6']],
    ['User 5100',['0.75','0.79','5','1.57','1.58','0.83','0.71','0.73']]
  ];
  const kind=v=>v===''?'blank':v.includes('⇥')?'broken':v==='0'?'zero':'ok';
  const TOT={broken:0,blank:0,zero:0}; ROWS.forEach(r=>r[1].forEach(v=>{const k=kind(v); if(k!=='ok') TOT[k]++;}));
  const NM={broken:'글자가 섞인 값',blank:'빈칸',zero:'0점'};
  let found;
  function why(u,ci,v){
    const k=kind(v), col=COLS[ci], nm=RV_KO[col];
    if(k==='broken') return v.startsWith('2')
      ?`<b>${u} · ${nm}</b> 「2⇥2.」처럼 숫자 사이에 탭 문자가 끼어 있어요. 이 칸 때문에 <b>지역 서비스 열 전체가 문자로</b> 읽혀요. 바로 옆 칸이 비어 있고, 이 줄의 뒤쪽 값들은 한 칸씩 밀렸을 수 있어요.`
      :`<b>${u} · ${nm}</b> 「.26」 뒤에 탭 문자가 붙어 있어요. 위아래 사용자의 값(1.03)과 비교하면 잘못 입력된 값으로 보여요.`;
    if(k==='blank') return `<b>${u} · ${nm}</b> 비어 있는 칸, 곧 <b>결측치</b>예요. 원본 파일에서는 이 줄의 마지막 값이 맨 끝의 이름 없는 빈 열로 밀려 있어요.`;
    if(k==='zero') return `<b>${u} · ${nm}</b> 구글 평점은 별 1~5개로 매기는데 정확히 0이에요. 그 장소 유형에 <b>평가를 남기지 않았다</b>는 뜻일 수 있어요. 전체 5,456명 중 ${nm} 0점은 ${rvFmt(RV.zeroCnt[col])}명이에요.`;
    return `<b>${u} · ${nm}</b> ${v} — 0보다 크고 5 이하인 평균 평점이라 그대로 써도 돼요.`;
  }
  function draw(){
    $('rvChk').innerHTML='<tr><th>User</th>'+COLS.map(c=>`<th>${RV_EN[c]}<small>${RV_KO[c]}</small></th>`).join('')+'</tr>'+
      ROWS.map(([u,vs],i)=>`<tr><th>${u}</th>`+vs.map((v,j)=>{const key=i+'-'+j, k=kind(v); return `<td data-k="${key}" tabindex="0" class="${found[key]?'f-'+k:''}">${v===''?'&nbsp;':esc(v)}</td>`;}).join('')+'</tr>').join('');
    $('rvChk').querySelectorAll('td').forEach(td=>{const f=()=>{
      const [i,j]=td.dataset.k.split('-').map(Number), v=ROWS[i][1][j];
      found[td.dataset.k]=1; td.className='f-'+kind(v); $('rvSay').innerHTML=why(ROWS[i][0],j,v); count();
    }; td.onclick=f; td.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();f();}};});
    count();
  }
  function count(){
    const got={broken:0,blank:0,zero:0};
    Object.keys(found).forEach(key=>{const [i,j]=key.split('-').map(Number), k=kind(ROWS[i][1][j]); if(k!=='ok') got[k]++;});
    const all=Object.keys(TOT).every(k=>got[k]===TOT[k]);
    $('rvFound').innerHTML=Object.keys(TOT).map(k=>`<span class="rv-c-${k}${got[k]===TOT[k]?' done':''}">${NM[k]} <b>${got[k]} / ${TOT[k]}</b></span>`).join('')+(all?'<span class="done">모두 찾았어요! 아래에서 처리 방법을 정해요.</span>':'');
  }
  $('rvChkReset').onclick=()=>{found={}; draw(); $('rvSay').innerHTML='칸을 누르면 그 값이 왜 이상한지(또는 괜찮은지) 알려 줘요.';};
  found={}; draw();
})();
