/* 02 이상치 줄 지우기 실험: 열을 고르면 그 열의 이상치가 있는 줄을 지운 뒤 남는 수 */
(function(){
  const B64='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const M=new Uint32Array(RV.n);
  for(let i=0;i<RV.n;i++){ let m=0; for(let t=0;t<4;t++) m|=B64.indexOf(RV.mask[4*i+t])<<(6*t); M[i]=m; }
  let sel=0;
  const box=$('rvIqrCols');
  box.innerHTML=RV_EN.map((e,i)=>`<button data-i="${i}" ${RV.outCnt[i]?'':'disabled'} title="${e}">${RV_KO[i]} <small>${rvFmt(RV.outCnt[i])}</small></button>`).join('');
  const bs=[...box.querySelectorAll('button')];
  function upd(){
    let left=0; for(let i=0;i<RV.n;i++) if(!(M[i]&sel)) left++;
    const p=left/RV.n*100, k=bs.filter((b,i)=>sel>>>i&1).length, kOut=RV.outCnt.filter(Boolean).length;
    bs.forEach((b,i)=>b.classList.toggle('on',!!(sel>>>i&1)));
    $('rvLeft').textContent=`남은 줄 ${rvFmt(left)} / ${rvFmt(RV.n)} (${p.toFixed(1)}%)`;
    $('rvLeftBar').style.width=p+'%';
    $('rvIqrSay').innerHTML=!k?`24개 열 가운데 이상치가 있는 열은 ${kOut}개예요. 공원·극장처럼 이상치가 하나도 없는 열은 누를 수 없어요. 열을 하나씩 눌러 보세요.`
      :k<kOut?`열 ${k}개에 이 규칙을 적용했더니 ${rvFmt(RV.n-left)}줄(${(100-p).toFixed(1)}%)이 지워졌어요. 열을 더 고르면 어떻게 될까요?`
      :`이상치가 있는 ${kOut}개 열 모두에 적용했더니 <b>${rvFmt(left)}줄</b>만 남았어요(교과서 결과 파일도 같은 방법으로 ${rvFmt(RV.kept)}줄). 지워진 사람 가운데에는 0점(평가 없음)이 많아 이상치가 된 경우가 많아요. 남은 사람들이 전체 사용자를 대표할 수 있을까요?`;
  }
  bs.forEach((b,i)=>b.onclick=()=>{sel^=(1<<i); sel>>>=0; upd();});
  $('rvIqrAll').onclick=()=>{sel=0; RV.outCnt.forEach((c,i)=>{if(c) sel|=(1<<i);}); sel>>>=0; upd();};
  $('rvIqrNone').onclick=()=>{sel=0; upd();};
  upd();
})();

/* 03 장소별 평균 평점 막대 */
(function(){
  let nz=false, sorted=false;
  function draw(){
    const v=nz?RV.meanNZ:RV.meanAll;
    let idx=[...Array(24).keys()]; if(sorted) idx.sort((a,b)=>v[b]-v[a]);
    $('rvBars').innerHTML=idx.map((i,k)=>{const d=RV.meanNZ[i]-RV.meanAll[i]; return `<div class="rv-b"><span class="n">${sorted?`<em>${k+1}</em> `:''}${RV_KO[i]}</span><span class="t"><i style="width:${v[i]/5*100}%;background:${RV_GC[RV_G[i]]}"></i></span><b>${v[i].toFixed(2)}</b>${nz&&d>=0.05?`<small>+${d.toFixed(2)}</small>`:''}</div>`;}).join('');
    $('rvZero').textContent=nz?'0점 포함해 보기':'0점 빼고 보기(평가 없음으로 보기)';
    $('rvSort').textContent=sorted?'원래 열 순서로':'평점 높은 순서로';
    $('rvBarSay').innerHTML=nz?'0점을 「평가 없음」으로 보고 빼고 평균을 냈어요. 초록 숫자는 0점을 포함했을 때보다 오른 만큼이에요. 0점이 많은 열일수록 평균이 많이 올라요.':'0점까지 점수로 넣어 평균을 냈어요(가로 막대 끝 = 5점). 0점이 많은 열은 평균이 낮아 보일 수 있어요.';
  }
  $('rvZero').onclick=()=>{nz=!nz; draw();};
  $('rvSort').onclick=()=>{sorted=!sorted; draw();};
  draw();
})();

/* 03 장소 평점 상관 탐색기 */
(function(){
  const SX=$('rvSelX'), SY=$('rvSelY'), S=$('rvPlot'), W=420, H=330, L=46, R=12, T=12, B=42, pw=W-L-R, ph=H-T-B;
  const opt=RV_KO.map((k,i)=>`<option value="${i}">${k} (${RV_EN[i]})</option>`).join('');
  SX.innerHTML=opt; SY.innerHTML=opt; S.setAttribute('viewBox',`0 0 ${W} ${H}`);
  const X=v=>L+v/5*pw, Y=v=>T+ph-v/5*ph;
  function word(r){ return r>=0.7?'뚜렷한 양의 상관관계':r>=0.3?'양의 상관관계가 보여요':r>-0.3?'상관관계가 거의 없어요':r>-0.7?'음의 상관관계가 보여요':'뚜렷한 음의 상관관계'; }
  function draw(){
    const a=+SX.value, b=+SY.value, only=$('rvKeepOnly').checked;
    let g=`<rect x="${L}" y="${T}" width="${pw}" height="${ph}" fill="#fbfaf7"/>`;
    for(let v=0; v<=5; v++) g+=`<line x1="${X(v)}" y1="${T}" x2="${X(v)}" y2="${T+ph}" stroke="#eceae4"/><line x1="${L}" y1="${Y(v)}" x2="${L+pw}" y2="${Y(v)}" stroke="#eceae4"/><text x="${X(v)}" y="${T+ph+15}" text-anchor="middle" font-size="11" fill="#5b6776">${v}</text><text x="${L-6}" y="${Y(v)+4}" text-anchor="end" font-size="11" fill="#5b6776">${v}</text>`;
    g+=`<path d="M${L} ${T}V${T+ph}H${L+pw}" fill="none" stroke="#16202c" stroke-width="2"/>`;
    g+=`<text x="${L+pw/2}" y="${H-5}" text-anchor="middle" font-size="12.5" font-weight="700" fill="#16202c">${RV_KO[a]} 평점 →</text><text x="13" y="${T+ph/2}" text-anchor="middle" font-size="12.5" font-weight="700" fill="#16202c" transform="rotate(-90 13 ${T+ph/2})">${RV_KO[b]} 평점 →</text>`;
    g+=RV.samp.filter(r=>!only||r[24]).map(r=>`<circle cx="${X(r[a]).toFixed(1)}" cy="${Y(r[b]).toFixed(1)}" r="4" fill="${r[24]?'#9b4fc4':'#8a94a3'}" fill-opacity="${r[24]?.85:.45}"/>`).join('');
    S.innerHTML=g;
    const ra=RV.corr[a][b], rk=RV.corrK[a][b], nShow=RV.samp.filter(r=>!only||r[24]).length;
    $('rvRAll').textContent=a===b?'1.00':rvNum(ra); $('rvRKeep').textContent=a===b?'1.00':rvNum(rk);
    $('rvRSay').innerHTML=a===b?'같은 장소를 두 축에 놓았어요. 다른 장소를 골라 보세요.'
      :`<b>${RV_KO[a]} × ${RV_KO[b]}</b> 전체: ${word(ra)} (r = ${rvNum(ra)}). 686명: r = ${rvNum(rk)}${Math.abs(ra-rk)>=0.15?' — <b>줄을 지운 뒤 상관계수가 크게 달라졌어요.</b>':'.'} <span class="muted">산점도 점 ${nShow}개(보라 = 686명에 남은 사람)</span>`;
  }
  const QUICK=[['극장 × 박물관',4,5],['박물관 × 아트 갤러리',5,14],['체육관 × 수영장',17,16],['식당 × 펍·바',8,9],['유적지 × 전망대',22,21]];
  $('rvQuick').innerHTML=QUICK.map((q,i)=>`<button class="btn ghost sm" data-i="${i}">${q[0]}</button>`).join('');
  $('rvQuick').querySelectorAll('button').forEach(b=>b.onclick=()=>{const q=QUICK[+b.dataset.i]; SX.value=q[1]; SY.value=q[2]; draw();});
  const pairs=[]; for(let i=0;i<24;i++) for(let j=i+1;j<24;j++) pairs.push([RV.corr[i][j],i,j]);
  pairs.sort((p,q)=>q[0]-p[0]);
  $('rvTop').innerHTML=pairs.slice(0,6).map(p=>`<button data-a="${p[1]}" data-b="${p[2]}">${RV_KO[p[1]]} × ${RV_KO[p[2]]} <b>${rvNum(p[0])}</b></button>`).join('');
  $('rvTop').querySelectorAll('button').forEach(b=>b.onclick=()=>{SX.value=b.dataset.a; SY.value=b.dataset.b; draw();});
  SX.onchange=draw; SY.onchange=draw; $('rvKeepOnly').onchange=draw;
  SX.value=4; SY.value=5; draw();
})();

